cat > docs/features/checkout-pricing/loyalty-discount.feature <<'EOF'
Feature: Loyalty discount

  # Open question for the business, deliberately without a scenario: the Platinum tier.
  # No reduction has been agreed, so no expected value exists.

  @loyalty-discount @happy-path
  Scenario: Bronze customer is charged the basket with the Bronze reduction
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @loyalty-discount @happy-path
  Scenario: Silver customer is charged the basket with the Silver reduction
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @loyalty-discount @happy-path
  Scenario: Gold customer is charged the basket with the Gold reduction
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @loyalty-discount @edge-case
  Scenario: Bronze customer with a tiny basket is charged on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    // Bronze customer is charged the basket with the Bronze reduction
    public void Bronze_customer_is_charged_the_basket_with_the_Bronze_reduction()
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
cat > src/CheckoutPricing.Application/CalculateLoyaltyDiscount.cs <<'EOF'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateLoyaltyDiscountQuery(int SubtotalCents, LoyaltyTier LoyaltyTier);

public sealed record LoyaltyDiscountQuote(
    int SubtotalCents,
    int DiscountCents,
    int TotalCents,
    LoyaltyTier LoyaltyTier);

public sealed class CalculateLoyaltyDiscount
{
    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query) => new(0, 0, 0, default);
}
EOF
